sp_CriarUsuario	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarUsuario`(\n\n    IN Login      VARCHAR(100),\n\n    IN Senha      VARCHAR(255),\n\n    IN Nome       VARCHAR(200),\n\n    IN CPF        VARCHAR(20),\n\n    IN Email      VARCHAR(200),\n\n    IN Telefone   VARCHAR(20),\n\n    IN dthCriacao DATETIME,\n\n    IN cargo_id   TINYINT UNSIGNED,\n\n    IN fAtivo     TINYINT(1)\n\n)\nBEGIN\n\n    INSERT INTO Usuario (Login, Senha, Nome, CPF, Email, Telefone, dthCriacao, cargo_id, fAtivo, idEmpresa)\n\n    VALUES (Login, Senha, Nome, CPF, Email, Telefone, dthCriacao, cargo_id, fAtivo, 1);\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
